<script lang="ts">
import {onMount} from 'svelte';import {api,type Book} from '../../lib/api';
export let bookId:number;
type Borrower={id:number;name:string;notes:string};type Loan={id:number;copy_id:number;borrower:string;checked_out_at:string;due_date:string|null;returned_at:string|null};
let book:Book|null=null;let borrowers:Borrower[]=[];let loans:Loan[]=[];let borrower='';let newName='';let due='';let busy=false;let error='';let message='';let loading=true;let adding=false;
const keys=new Map<string,string>();function requestKey(payload:string){if(!keys.has(payload))keys.set(payload,crypto.randomUUID());return keys.get(payload)!;}
async function load(){try{[book,borrowers,loans]=await Promise.all([api<Book>(`/api/books/${bookId}`),api<Borrower[]>('/api/borrowers'),api<Loan[]>(`/api/books/${bookId}/loans`)]);}catch(e){error=(e as Error).message;}finally{loading=false;}}
onMount(()=>{load();const refresh=()=>load();window.addEventListener('focus',refresh);window.addEventListener('library-inventory-changed',refresh);return()=>{window.removeEventListener('focus',refresh);window.removeEventListener('library-inventory-changed',refresh);};});
function active(copyId:number){return loans.find(l=>l.copy_id===copyId&&!l.returned_at);}
async function addBorrower(){if(!newName.trim())return;busy=true;error='';const payload=JSON.stringify(['borrower',newName.trim()]);try{const result=await api<{id:number}>('/api/borrowers',{name:newName.trim(),notes:'',request_key:requestKey(payload)});keys.delete(payload);await load();borrower=String(result.id);newName='';adding=false;message='Borrower added.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
async function checkout(copyId:number){if(!borrower)return;busy=true;error='';const payload=JSON.stringify(['checkout',copyId,borrower,due]);try{await api('/api/loans',{copy_id:copyId,borrower_id:Number(borrower),due_date:due,request_key:requestKey(payload)});keys.delete(payload);await load();message='Book checked out.';window.dispatchEvent(new Event('library-inventory-changed'));}catch(e){error=(e as Error).message;await load();}finally{busy=false;}}
async function returnLoan(id:number){busy=true;error='';const payload=`return-${id}`;try{await api(`/api/loans/${id}/return`,{request_key:requestKey(payload)});keys.delete(payload);await load();message='Book returned.';window.dispatchEvent(new Event('library-inventory-changed'));}catch(e){error=(e as Error).message;await load();}finally{busy=false;}}
</script>
<section class="lending_wrap" aria-labelledby="lending-title"><h3 id="lending-title">Lending</h3>
{#if error}<p role="alert" class="library-error">{error}</p>{/if}
{#if loading}<p>Loading loans…</p>{:else if book}
{#if book.available>0}<div class="lending_options"><label class="library-field">Lend to<select bind:value={borrower} disabled={busy}><option value="">Choose a borrower</option>{#each borrowers as b}<option value={b.id}>{b.name}</option>{/each}</select></label><label class="library-field">Due date (optional)<input type="date" bind:value={due} disabled={busy}/></label><button class="library-button secondary" onclick={()=>adding=!adding} disabled={busy}>{adding?'Cancel':'New borrower'}</button></div>
{#if adding}<form class="lending_options" onsubmit={(e)=>{e.preventDefault();addBorrower();}}><label class="library-field">Borrower name<input bind:value={newName} maxlength="200" required disabled={busy}/></label><button class="library-button" disabled={busy||!newName.trim()}>Add borrower</button></form>{/if}{/if}
{#each book.copies as copy}{@const loan=active(copy.id)}<div class="lending_copy"><div><strong>{copy.label||`Copy ${copy.id}`}</strong><p>{copy.shelf}</p>{#if loan}<p>Lent to <strong>{loan.borrower}</strong> · Checked out {loan.checked_out_at.slice(0,10)}{#if loan.due_date} · Due {loan.due_date}{/if}</p>{:else if copy.out}<p>On loan. Refresh to load its details.</p>{:else}<p>Available</p>{/if}</div>{#if loan}<button class="library-button" disabled={busy} onclick={()=>returnLoan(loan.id)}>Return book</button>{:else if !copy.out}<button class="library-button secondary" disabled={busy||!borrower} onclick={()=>checkout(copy.id)}>Check out</button>{/if}</div>{/each}
{#if loans.some(l=>l.returned_at)}<details><summary>Loan history</summary><ul>{#each loans.filter(l=>l.returned_at) as loan}<li>{loan.borrower} · Lent {loan.checked_out_at.slice(0,10)} · Returned {loan.returned_at?.slice(0,10)}</li>{/each}</ul></details>{/if}
{/if}<p role="status">{message}</p></section>
<style>@layer components{.lending_wrap{display:grid;gap:var(--space-4);h3{font-size:var(--h5)}}.lending_options{display:flex;flex-wrap:wrap;gap:var(--space-3);align-items:end;label{flex:1;min-width:12rem}}.lending_copy{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:var(--space-3);border:var(--border-width) solid var(--border);padding:var(--space-4);border-radius:var(--radius-main);background:var(--background-3)}.lending_wrap details ul{padding-left:var(--space-4)}} </style>
